#!/usr/bin/env python3
"""Generated files in a wagon train (hal2 plan 0313 step 8, D13): a conflict only in files a tool writes is no
unhitch. Every foreman regenerates `plans/uats.md`, the code maps and the record index, so cars conflict with the
barn and with each other only there (07 and 13 on plans/uats.md, 2026-10-14).

The one list is the repository's own, the landing's (hal2-git `versions::generated`): `.github/hal2-versions.toml`'s
`[[generated]]` entries, each a `command` that prints `{"files": {<path>: <text>}, "problems": [...]}` (with
`--rev <commit>` appended: that commit read from git's objects) and the `paths` (globs, a `*` within one segment)
it owns. The map is read at a rev, as the landing reads it; a repository without one has no generated file.

- `only`: whether every file of a conflict is generated (trains.draft: the car rides)
- `take`: a merge in the carrier stopped on such a conflict, finished with the barn's side (engine.form)
- `regenerate`: after all cars, the commands' files for the carrier's head, committed as the train's last commit
"""

import json
import subprocess
import tomllib
from fnmatch import fnmatchcase
from pathlib import Path

import origin

MAP = ".github/hal2-versions.toml"
SUBJECT = "chore(generated): write the generated files again after the train's merges"
DATA = ("plans/*/uat-results.jsonl",)  # generated, but append-only committed verdicts: never the barn's side (D16)


def git(top: str, *args: str) -> tuple[int, str]:
    p = subprocess.run(["git", *args], cwd=top, capture_output=True, text=True, timeout=600)
    return p.returncode, (p.stdout + p.stderr).strip()


def entries(top: str, rev: str = "HEAD") -> list[dict]:
    """The map's `[[generated]]` entries at `rev` ({command, paths}); none without a map or with one that does not
    parse."""
    code, text = git(top, "show", f"{rev}:{MAP}")
    try:
        found = tomllib.loads(text).get("generated", []) if code == 0 else []
    except tomllib.TOMLDecodeError:
        return []
    return [g for g in found if isinstance(g, dict) and g.get("command") and g.get("paths")]


def matches(pattern: str, path: str) -> bool:
    """Segment by segment, a `*` for any characters within one (the landing's `generated::matches`)."""
    want, have = pattern.split("/"), path.split("/")
    return len(want) == len(have) and all(fnmatchcase(h, w) for w, h in zip(want, have))


def generates(found: list[dict], path: str) -> bool:
    return any(matches(p, path) for g in found for p in g["paths"])


def in_blocks(text: str) -> bool:
    """Every conflict of a merged file lies in a generated block (`<!-- generated: <name> -->` to `<!-- /generated
    -->`: INTENT.md's log, AGENTS.md's Rules); a file without such a block is generated whole. A conflict in the
    hand-written part of such a file is a person's, never taken from the barn."""
    lines = text.splitlines()
    if not any(line.strip().startswith("<!-- generated:") for line in lines):
        return True
    block = False
    for line in lines:
        if line.strip().startswith("<!-- generated:"):
            block = True
        elif line.strip() == "<!-- /generated -->":
            block = False
        elif line.startswith(("<<<<<<< ", ">>>>>>> ")) and not block:
            return False
    return True


def only(top: str, rev: str, files: list[str], merged: str | None = None) -> bool:
    """Every file of a conflict is generated by the map at `rev`, its conflicts within the generated blocks: read
    from the trial's commit `merged`, or the working tree of a merge stopped in `top`."""
    found = entries(top, rev)
    if not files or not found or not all(generates(found, f) for f in files):
        return False
    if any(matches(d, f) for d in DATA for f in files):
        return False
    return all(in_blocks(git(top, "show", f"{merged}:{f}")[1] if merged else _read(Path(top) / f)) for f in files)


def _read(path: Path) -> str:
    return path.read_text(errors="replace") if path.is_file() else ""


def take(top: str, side: str) -> list[str]:
    """A merge stopped in `top`: when its conflicts are all generated files (by the map at HEAD), each takes `side`
    (`--ours`: the carrier, the barn with the cars ahead; `--theirs`: the barn merged into the carrier) and the merge
    is committed. The files taken; [] leaves the merge as it was."""
    files = git(top, "diff", "--name-only", "--diff-filter=U")[1].splitlines()
    if not only(top, "HEAD", files):
        return []
    for f in files:
        kept = git(top, "checkout", side, "--", f)[0] == 0  # a side that deleted the file has none to check out
        if git(top, *(["add"] if kept else ["rm", "-q"]), "--", f)[0]:
            return []
    return files if git(top, "commit", "-q", "--no-edit", "--cleanup=strip")[0] == 0 else []


def printed(top: str, g: dict, rev: str) -> dict:
    """One command's files for `rev`, those within its paths; ValueError with its problems when it fails."""
    name = " ".join(g["command"])
    try:
        p = subprocess.run([*g["command"], "--rev", rev], cwd=top, capture_output=True, text=True, timeout=600)
    except (OSError, subprocess.TimeoutExpired) as e:
        raise ValueError(f"{name}: {e}") from e
    try:
        out = json.loads(p.stdout)
    except json.JSONDecodeError:
        out = None
    if p.returncode or not isinstance(out, dict):
        why = "; ".join((out or {}).get("problems") or []) if isinstance(out, dict) else ""
        raise ValueError(f"{name}: {why or p.stderr.strip()[-300:] or 'printed no JSON'}")
    return {f: text for f, text in (out.get("files") or {}).items() if any(matches(x, f) for x in g["paths"])}


def regenerate(top: str, taken: list[str], fields: list[str] | None = None) -> tuple[int, str, str | None, list[str]]:
    """Every command of the map at HEAD prints its files for HEAD; those that differ are written and committed
    (`taken`, the conflicts that were taken, go into the message; `fields`, the cars' fields, its `Worktree:` trailer).
    The exit code (1: a command failed, or a taken file none prints), what happened, the commit (None: nothing
    differed) and the files written."""
    head = git(top, "rev-parse", "HEAD")[1]
    files: dict[str, str] = {}
    try:
        for g in entries(top, head):
            files.update(printed(top, g, head))
    except ValueError as e:
        return 1, f"the generated files were not written again: {e}", None, []
    missing = [f for f in taken if f not in files and git(top, "cat-file", "-e", f"{head}:{f}")[0] == 0]
    if missing:
        return 1, f"the generated files were not written again: no command prints {', '.join(missing[:5])}", None, []
    written = []
    for f, text in sorted(files.items()):
        path = Path(top) / f
        if path.is_file() and path.read_text() == text:
            continue
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text)
        if git(top, "add", "--", f)[0]:
            return 1, f"the generated file {f} was not staged", None, []
        written.append(f)
    if not written:
        return 0, "the generated files were up to date", None, []
    code, out = git(top, "commit", "-q", "-m", SUBJECT, "-m", "Conflicts taken from the barn: " + ", ".join(taken)
                    + ".\nWritten again by .github/hal2-versions.toml's [[generated]] commands: " + ", ".join(written),
                    "-m", origin.trailers(fields or [Path(top).name]))
    if code:
        return 1, f"the generated files were not committed: {out[-300:]}", None, []
    return 0, f"the generated files written again ({len(written)})", git(top, "rev-parse", "HEAD")[1], written
